#include <iostream>
#include <string>
using namespace std;

class Cat {
protected:
    string name;
public:
    Cat(string n) : name(n) {
        cout << "搭猫妈妈那一半：" << name << endl;
    }
    virtual ~Cat() {
        cout << "拆猫妈妈那一半：" << name << endl;
    }
};

class Kitten : public Cat {
public:
    Kitten(string n) : Cat(n) {
        cout << "搭小猫那一半：" << name << endl;
    }
    ~Kitten() {
        cout << "拆小猫那一半：" << name << endl;
    }
};

int main() {
    Cat* p = new Kitten("{name}");
    delete p;
    return 0;
}
